// Kun når button trykkes (LOW = 0 med pull-up)
if (msg.payload === 0 || msg.payload === "0") {

    var gates = [
        "rundsav",
        "disponibel",
        "stor_cnc",
        "lille_cnc",
        "rondelsliber",
        "baandsliber"
    ];

    var messages = [];

    // Send CLOSE kommando til hver gate
    for (var i = 0; i < gates.length; i++) {
        messages.push({
            topic: "spansug/gate/" + gates[i] + "/cmd",
            payload: "CLOSE"
        });
    }

    // Log event
    node.warn("🛑 EMERGENCY STOP - Lukker alle gates!");

    return [messages];
}

return null;

