// Initialize gate states in flow context
let gates = flow.get('gates') || {};

// Extract gate ID from topic (e.g., "spansug/gate/rundsav_auto/cmd" -> "rundsav_auto")
const topicParts = msg.topic.split('/');
const gateId = topicParts[2];
const command = msg.payload;

// Update gate state
if (command === 'OPEN' || command === 'WAIT' || command === 'ÅBEN') {
    gates[gateId] = 'OPEN';
} else if (command === 'CLOSE' || command === 'LUKKET') {
    gates[gateId] = 'CLOSED';
}

// Save updated states
flow.set('gates', gates);

// Count open gates
let openCount = 0;
for (let gate in gates) {
    if (gates[gate] === 'OPEN') {
        openCount++;
    }
}

// Decide relay state
if (openCount > 0) {
    msg.payload = 1;  // Relay ON
    msg.status = openCount + ' gate(s) open';
} else {
    msg.payload = 0;  // Relay OFF
    msg.status = 'All gates closed';
}

return msg;

